WITH ranked AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY level ORDER BY hire_date, id) AS dedup_rank FROM employees) ranked WHERE dedup_rank = 1) SELECT CASE WHEN salary >= 123000 THEN 'LARGE' ELSE 'SMALL' END AS salary_tier, COUNT(DISTINCT job_title) AS distinct_job_titles, COUNT(CASE WHEN job_title = 'Intern' THEN 1 END) AS intern_count, SORT_ARRAY(COLLECT_SET(job_title)) AS job_title_list, PERCENTILE_APPROX(salary, 0.5) AS salary_p50, AVG(salary) FILTER (WHERE job_title = 'Director') AS director_avg_salary, COUNT(DISTINCT job_title) AS distinct_job_titles_2 FROM ranked GROUP BY CASE WHEN salary >= 123000 THEN 'LARGE' ELSE 'SMALL' END ORDER BY intern_count DESC NULLS LAST
